"""Contract-test setup: each sample checked against its folder's JSON Schema.

The schemas use a small subset of JSON Schema (type, properties, required, additionalProperties,
items, minItems, minLength, pattern, minimum, maximum, exclusiveMinimum); `schema_errors` checks
that subset, so the project needs no validator dependency.
"""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

import pytest

CONTRACTS = Path(__file__).resolve().parent

JSON_TYPES: dict[str, tuple[type, ...]] = {
    "object": (dict,),
    "array": (list,),
    "string": (str,),
    "number": (int, float),
    "integer": (int,),
    "boolean": (bool,),
    "null": (type(None),),
}


def _type_ok(value: Any, names: str | list[str]) -> bool:
    for name in [names] if isinstance(names, str) else names:
        is_bool = isinstance(value, bool)
        if name == "boolean" and is_bool:
            return True
        if name != "boolean" and not is_bool and isinstance(value, JSON_TYPES[name]):
            return True
    return False


def _bound_errors(value: Any, schema: dict[str, Any], where: str) -> list[str]:
    errors = []
    if isinstance(value, str):
        if len(value) < schema.get("minLength", 0):
            errors.append(f"{where}: shorter than {schema['minLength']}")
        if "pattern" in schema and not re.search(schema["pattern"], value):
            errors.append(f"{where}: {value!r} does not match {schema['pattern']}")
    if isinstance(value, int | float) and not isinstance(value, bool):
        if "minimum" in schema and value < schema["minimum"]:
            errors.append(f"{where}: {value} < {schema['minimum']}")
        if "maximum" in schema and value > schema["maximum"]:
            errors.append(f"{where}: {value} > {schema['maximum']}")
        if "exclusiveMinimum" in schema and value <= schema["exclusiveMinimum"]:
            errors.append(f"{where}: {value} <= {schema['exclusiveMinimum']}")
    return errors


def schema_errors(value: Any, schema: dict[str, Any], where: str = "$") -> list[str]:
    """Every way `value` breaks `schema`, as `<json path>: <reason>`; empty when it is valid."""
    if "type" in schema and not _type_ok(value, schema["type"]):
        return [f"{where}: {value!r} is not {schema['type']}"]
    errors = _bound_errors(value, schema, where)
    if isinstance(value, list):
        if len(value) < schema.get("minItems", 0):
            errors.append(f"{where}: fewer than {schema['minItems']} items")
        for i, item in enumerate(value):
            errors += schema_errors(item, schema.get("items", {}), f"{where}[{i}]")
    if isinstance(value, dict):
        errors += [f"{where}: missing {key}" for key in schema.get("required", []) if key not in value]
        properties = schema.get("properties", {})
        extra = schema.get("additionalProperties", {})
        for key, item in value.items():
            if key in properties:
                errors += schema_errors(item, properties[key], f"{where}.{key}")
            elif extra is False:
                errors.append(f"{where}: unexpected {key}")
            else:
                errors += schema_errors(item, extra, f"{where}.{key}")
    return errors


